requests.testScript:
pw.test('SQLi authenticated us', () => {
  pw.expect(pw.response.status).toBe(200);
  const token = pw.response.body.authentication.token;
  pw.expect(token).not.toBe(undefined);
  pw.env.set('token', token);
});

pw.test('input reaches SQL (injectable)', () => {
  pw.expect(pw.response.body).toInclude('SQLITE_ERROR');
});
